// frontend/src/App.js

import React, { useState, useEffect } from "react";
import { sendRequest } from "./requests/requests";
import "./App.css";

function App() {
  const [imageFile, setImageFile] = useState(null);
  const [secondImage, setSecondImage] = useState(null);
  const [operation, setOperation] = useState("gray");
  const [params, setParams] = useState({});
  const [resultUrl, setResultUrl] = useState("");
  const [previewUrl, setPreviewUrl] = useState("");
  const [previewSecond, setPreviewSecond] = useState("");

  useEffect(() => {
    const defaults = {
      binary: { threshold: 127 },
      rotate: { angle: 90 },
      zoom: { scale: 1.2 },
      contrast: { factor: 0.5 },
      median: { kernel_size: 3 },
      motion: { kernel_size: 3 },
      color: { mode: "HSV" },
      double_threshold: { low_thresh: 50, high_thresh: 150 },
      edge: { threshold1: 100, threshold2: 200 },
      crop: { x: 0, y: 0, width: 200, height: 200 },
      noise: { amount: 0.02 },
      denoise: { filter_type: "mean", kernel_size: 3 },
      morphology: { morph_op: "dilate", kernel_size: 3 },
      arithmetic: { arithmetic_op: "subtract" },
    };
    setParams(defaults[operation] || {});
    setSecondImage(null);
    setPreviewSecond("");
    setResultUrl("");
  }, [operation]);

  const handleSubmit = async () => {
    if (!imageFile) {
      alert("Lütfen bir görsel yükleyin.");
      return;
    }

    const formData = new FormData();
    formData.append("operation", operation);
    formData.append("file", imageFile);
    if (secondImage) formData.append("file2", secondImage);

    Object.keys(params).forEach((key) => {
      formData.append(key, params[key]);
    });

    try {
      const data = await sendRequest({ operation, imageFile, secondImageFile: secondImage, params });

      if (data?.url) {
        setResultUrl(data.url);
      } else {
        alert("İşlem başarısız oldu.");
        setResultUrl("");
      }
    } catch (error) {
      alert("Bir hata oluştu.");
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImageFile(file);
    if (file) setPreviewUrl(URL.createObjectURL(file));
  };

  const handleSecondImageChange = (e) => {
    const file = e.target.files[0];
    setSecondImage(file);
    if (file) setPreviewSecond(URL.createObjectURL(file));
  };

  const updateParam = (key, value) => {
    setParams((prev) => ({ ...prev, [key]: value }));
  };

  const renderParams = () => {
    switch (operation) {
      case "binary":
        return <input type="number" value={params.threshold} onChange={(e) => updateParam("threshold", e.target.value)} />;
      case "rotate":
        return <input type="number" value={params.angle} onChange={(e) => updateParam("angle", e.target.value)} />;
      case "zoom":
        return <input type="number" value={params.scale} onChange={(e) => updateParam("scale", e.target.value)} />;
      default:
        return null;
    }
  };

  return (
    <div>
      <input type="file" onChange={handleImageChange} />
      <button onClick={handleSubmit}>Uygula</button>
      {resultUrl && <img src={resultUrl} />}
    </div>
  );
}

export default App;
